insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('culture', 'Start Here', NULL, 'Culture & Conduct', '[{"t":"p","x":"The 5 Pillars are how we think. The Doctrine is how we operate. The Redlines are what ends employment. Leaders included: lead by example."},{"t":"h2","x":"The 5 Pillars"},{"t":"table","head":["Pillar","In short"],"rows":[["Ownership Mentality","Own your tasks and outcomes. No excuses, no blame, finish what you start."],["Progress Over Perfection","Move and deliver fast, then improve on real feedback. Done beats drafted."],["Data-Driven Thinking","Decide on numbers and clear reasoning, not assumptions or feelings."],["Continuous Growth","Get a little better every week. Learn from mistakes, build better habits."],["Team Before Ego","Put team success above personal ego. No gossip, no politics, open to feedback."]]},{"t":"h2","x":"Company Doctrine"},{"t":"steps","ordered":false,"x":["Company comes first","Ownership over excuses","System over individuals","Loyalty and trust are earned","Discipline creates freedom","Data over assumption","Leaders lead by example","Improve every month","No toxic behavior","Build something bigger"]},{"t":"h2","x":"Redlines — zero tolerance"},{"t":"callout","tone":"warn","title":"Immediate termination","x":"Data betrayal · Player or financial misconduct · Theft or fraud · Unauthorized player handling · Security violations · Dishonesty with leadership · External business conflicts · Substance abuse on duty · Public defamation · Unauthorized contact with ex-staff."}]', '["V1.0","Everyone reads this first","Updated 17 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', 'pillars doctrine redlines values conduct ownership integrity', 1);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('department-overview', 'Start Here', NULL, 'Department Overview', NULL, NULL, 'V1.0', 'ATL', 0, 'pending', 'mission scope brands tiers roles about', 2);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('team-structure', 'Start Here', NULL, 'Team Structure', NULL, NULL, 'V1.0', 'ATL', 0, 'pending', 'org chart headcount roles about', 3);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('case-study-logging', 'SOP Book', 'Governance & Integrity', 'Case Study Logging', '[{"t":"p","x":"**Applies to:** All VIP CS; Senior and ATL review"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Capture real incidents into the Case Study Library so the team learns from cases, not only from procedure."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Any notable operational error, player abuse or exploit, or provider/system issue worth learning from."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Real incidents only. Never invent a case to fill a category.","Role titles only. No staff or player names, no player IDs or UIDs.","\"What we learn\" is the point of the row; keep it to what a reader should do differently."]},{"t":"h2","x":"4. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Spot a case worth logging","On a notable incident","Real incident with a lesson; skip the trivial","Chat, BO, reports"],["2","Categorise and rate severity","After spotting","Operational Error / Player Abuse-Exploit / Provider-System Issue; severity Critical/High/Medium/Low","Category definitions"],["3","Write the case row","After categorising","What Happened, Why It Happened, What We Learn, Rule or SOP it maps to; role titles only","Case Study Library"],["4","Link the full write-up","If detailed","Summary in the library, full write-up in a Lark Doc, link in Reference","Lark Docs"],["5","Review and fold back","Periodically","Senior/ATL review; if a case reveals an SOP gap, feed it to the SOP owner","SOP Book"]]},{"t":"h2","x":"5. Guards"},{"t":"list","x":["Real only; no names or UIDs; the lesson is the point."]},{"t":"h2","x":"6. Remarks"},{"t":"list","x":["Source reports stay credited to their original authors. The library is the summary, not a replacement."]}]', '["C9MYR-RTN-SOP-GOV02","V1.0","Governance / Learning","Owner: VIP RTN","Updated 5 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', 'incident exploit lesson severity case study', 4);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('reporting-data-integrity', 'SOP Book', 'Governance & Integrity', 'Reporting & Data Integrity', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 5);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('escalation', 'SOP Book', 'Governance & Integrity', 'Escalation', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 6);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('process-landing-layer', 'SOP Book', 'Governance & Integrity', 'Process Landing Layer', '[{"t":"p","x":"**Applies to:** ATL, Senior, process owners"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Make the SOP Book a working system, not a document set. These five tools cover Methods 5, 7, 8, 9 and 10, so every SOP is validated, trained, monitored, reviewed and archived."},{"t":"h2","x":"2. How the book maps to the 10 methods"},{"t":"table","head":["Method","Where it lives in the book"],"rows":[["1 Design team, owner","Owner field on every SOP"],["2 Identify high-value SOPs","SOP coverage map (priority order)"],["3 Benchmark, co-create","Sourcing thin SOPs from the top performer"],["4 Write the SOP (4 elements)","The SOP template"],["5 Validate, trial-run","Validation checklist (below)"],["6 Manager confirm, release","Sign-off + effective date on release"],["7 Train, everyone executes","Training checklist (below)"],["8 Monitor, check","Monitoring metrics (below)"],["9 Review, iterate","Review log (below)"],["10 Archive, bank knowledge","Archive standard (below)"]]},{"t":"h2","x":"3. Validation checklist (Method 5)"},{"t":"p","x":"Before release, trial-run on 1-2 people for 1-2 weeks, then confirm:"},{"t":"list","x":["Are the steps clear enough for a normal person to follow?","Are the tools named and usable?","Do the exceptions have a plan?","Feedback collected and fixed; re-tested until smooth."]},{"t":"p","x":"A process is tested out, not designed out."},{"t":"h2","x":"4. Training checklist (Method 7)"},{"t":"p","x":"Three stages, each with a gate:"},{"t":"list","x":["Awareness: read the SOP / attend the briefing (knows what it is).","Skill: drill + assessment passed (can do it).","Willingness: benefit explained, questions answered (wants to use it)."]},{"t":"p","x":"Landing: SOP online + on the daily task checklist with KPI."},{"t":"h2","x":"5. Monitoring metrics (Method 8)"},{"t":"table","head":["Metric","Formula","Cadence","Owner"],"rows":[["Execution rate","SOP-followed / total","Weekly","Process owner"],["Error rate","Not-followed / total","Monthly","Ops"],["Effect","Problems solved / effectiveness","Quarterly","Management"]]},{"t":"p","x":"Correction: not-followed to coach to warn; problem found to feedback to improve. A process with no check is a decoration on the wall."},{"t":"h2","x":"6. Review log (Method 9)"},{"t":"p","x":"Trigger a review on: schedule (quarterly), a problem, or a business change. Ask three questions:"},{"t":"list","x":["Is it still solving the problem?","Is it simple enough?","Does it need updating?"]},{"t":"p","x":"Bump the version and record what changed. Yesterday''s process can be today''s problem."},{"t":"h2","x":"7. Archive standard (Method 10)"},{"t":"list","x":["Unified format (this template), clear directory, quick to find (indexed), permissioned (who views, who edits).","For new hires: the docs are required reading, the teaching material, and an exam item.","Keep the version history."]},{"t":"p","x":"Documents are the department''s cheapest trainer."},{"t":"h2","x":"8. Remarks"},{"t":"p","x":"This layer is what makes the SOP Book read as above-expectation: it shows the process is designed, validated, trained, watched, and improved, not just written."}]', '["C9MYR-RTN-SOP-GOV03","V1.0","Governance","Owner: ATL","Updated 5 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', NULL, 7);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('grace', 'SOP Book', 'Money Control & Bonuses', 'Grace Period List', '[{"t":"h2","x":"Objective"},{"t":"p","x":"Filter eligible Grace Period players and send targeted Internal Mail to re-engage them before the grace window expires. First daily task, once the feed lands."},{"t":"h2","x":"Sending schedule"},{"t":"table","head":["Day","Action"],"rows":[["Monday","Grace Period Player IM (List A)"],["Tuesday","Potential Player IM (List B)"],["Thursday","Follow-up List A"],["Friday","Follow-up List B"],["Wed / Sat / Sun","No Grace IM"]]},{"t":"h2","x":"Procedure"},{"t":"steps","x":["Receive the Grace Period database from Retention Admin (Handover tab).","Copy into the Customer Approaching Lark Base, Grace Period (Day). Paste values only.","Filter Valid vs Invalid by brand and status.","Valid: pass list to Admin for SMS, CS sends IM + Push. Invalid: IM + Push only, no bonus mention.","Update the QA Record with a BO screenshot."]},{"t":"h2","x":"Bonus ladder"},{"t":"table","head":["Tier","Deposit","Free bonus","Cap"],"rows":[["T3","RM 100","RM 18","SW × 20%"],["T3","RM 500","RM 58","SW × 20%"],["TV","RM 600","RM 68","SW × 20%"],["TV","RM 900","RM 98","SW × 20%"]]},{"t":"callout","tone":"good","title":"Guardrails","x":"Contact before any deposit credit. Never contact HEALTHY or WATCH players. Counts are weighted, never a simple average."}]', '["V1.0","Day Shift","Owner: ATL","Updated 13 May 2026"]', 'V1.0', 'ATL', 0, 'live', 'bonus deposit grace expiry re-engage internal mail day shift', 8);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('birthday-bonus', 'SOP Book', 'Money Control & Bonuses', 'Birthday Bonus', NULL, NULL, 'V1.0', 'ATL', 0, 'external', 'birthday bonus', 9);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('weekend-campaign', 'SOP Book', 'Money Control & Bonuses', 'Weekend Campaign', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Run the weekend-only campaign every Saturday and Sunday. Three components: Ang Bao, Free Spin, and Deposit Challenge (under testing). Each has distinct tier and platform targeting."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Saturday and Sunday only. Issuing any component on a weekday is a process violation."},{"t":"table","head":["Day","Active","Ang Bao","Free Spin","Deposit Challenge"],"rows":[["Mon to Fri","No","-","-","-"],["Saturday","Yes","Active","Active","Under testing"],["Sunday","Yes","Active","Active","-"]]},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["The whole campaign runs Saturday and Sunday only. A weekday issuance is a process violation.","Ang Bao is TC only; Free Spin is Zyra only. Never cross-issue.","Ang Bao tier split is strict: Normal (RM 2 to 8) Tier 3, Special (RM 8 to 18) Tier V.","Deposit Challenge is under testing. Confirm with ATL or TL before any issuance.","If a player''s tier is unclear, verify in the BO before issuing any weekend reward."]},{"t":"h2","x":"4. Component 1: Ang Bao (TC only)"},{"t":"table","head":["Type","Amount","Tier","Platform"],"rows":[["Normal Ang Bao","RM 2 to RM 8","Tier 3 only","TC"],["Special Ang Bao","RM 8 to RM 18","Tier V only","TC"]]},{"t":"list","x":["Tier 3 gets Normal only, Tier V gets Special only. Never cross-issue.","TC platform only. Not applicable on Zyra.","Weekend only."]},{"t":"h2","x":"5. Component 2: Free Spin (Zyra only) [DISCONTINUED]"},{"t":"p","x":"**Discontinued from September 2026. Do not issue Free Spin. Kept here for reference only.**"},{"t":"table","head":["Type","Spins","Tier","Platform"],"rows":[["Standard","20 Free Spins","Tier 3","Zyra"],["Enhanced","30 Free Spins","Tier V","Zyra"]]},{"t":"list","x":["Zyra brands only. Not applicable on TC.","Weekend only.","The tier split (20 vs 30 spins) and issuance method are no longer relevant; the component is discontinued (September 2026)."]},{"t":"h2","x":"6. Component 3: Deposit Challenge (UNDER TESTING)"},{"t":"p","x":"Do not implement without explicit ATL or TL sign-off. Reward structure confirmed; operational procedure pending."},{"t":"table","head":["Deposit","Extra Reward","Net Benefit (cumulative)"],"rows":[["RM 588","RM 38","RM 38"],["RM 1,008","RM 88","RM 126"],["RM 1,888","RM 188","RM 314"],["RM 3,088","RM 388","RM 702"],["RM 8,888","RM 1,288","RM 1,990"]]},{"t":"list","x":["The extra reward is added on top of the deposit.","Step-up is cumulative: a higher tier unlocks all lower tiers too. Example: deposit RM 1,888 gives RM 188 + RM 88 + RM 38 = RM 314 extra.","Platform, issuance method, eligible tiers and ticket query all pending TL confirmation."]},{"t":"h2","x":"7. Guards"},{"t":"list","x":["A weekday issuance of any component is a process violation.","Ang Bao (TC only) and Free Spin (Zyra only) are on different platforms; do not cross-issue.","Deposit Challenge is under testing; confirm with ATL or TL before any issuance.","If a player''s tier is unclear, verify in the BO before issuing."]},{"t":"h2","x":"8. Remarks"},{"t":"list","x":["Ang Bao tier split is strict: Normal (RM 2 to 8) Tier 3, Special (RM 8 to 18) Tier V.","Free Spin tier/spin distinction and issuance method are pending ATL / PIC confirmation."]}]', '["C9MYR-RTN-SOP-B01","V1.1","Bonus / Strategy","Owner: VIP RTN / ATL","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'angpao ang bao free spin deposit challenge saturday sunday', 10);
